import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;

public class Harness {
    /** Every wait in this harness is bounded by this; the watchdog is the last resort. */
    private static final long DEADLINE_MS = 5_000L;
    /**
     * How long a worker keeps holding a lock while it waits to be released. It must
     * outlast every deadline main can spend before releasing it (3 x DEADLINE_MS in
     * the write-preference check), or a worker letting go on its own timeout could
     * fake the very thing the check is proving.
     */
    private static final long HOLD_MS = 25_000L;

    public static void main(String[] args) {
        Atrophy.plan(4);
        Atrophy.watchdog(30000);
        try {
            concurrentReaders();
            exclusiveWriters();
            writePreference();
            Atrophy.check("harness completed every check without crashing", true);
        } catch (Throwable t) {
            Atrophy.check("harness crashed: " + t, false);
        } finally {
            Atrophy.report();
        }
    }

    private static Thread daemon(String name, Runnable body) {
        Thread t = new Thread(body, name);
        t.setDaemon(true);
        t.start();
        return t;
    }

    /**
     * Bounded wait for a thread to park inside a lock call. Returns false the moment
     * `acquired` trips (it took the lock instead of queueing) or the thread dies.
     * A latch cannot express "is blocked", so this polls thread state with a deadline.
     */
    private static boolean awaitParked(Thread t, BooleanSupplier acquired) {
        long end = System.nanoTime() + DEADLINE_MS * 1_000_000L;
        while (System.nanoTime() < end) {
            if (acquired.getAsBoolean()) return false;
            Thread.State s = t.getState();
            if (s == Thread.State.TERMINATED) return false;
            if (s == Thread.State.WAITING || s == Thread.State.TIMED_WAITING || s == Thread.State.BLOCKED) {
                return !acquired.getAsBoolean();
            }
            try {
                Thread.sleep(1);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }
        return false;
    }

    /** Check 1: two readers are inside the lock at the same time (proved by latch, not timing). */
    private static void concurrentReaders() throws InterruptedException {
        Solution lock = new Solution();
        CountDownLatch settled = new CountDownLatch(2); // counts down on acquire OR on failure
        CountDownLatch release = new CountDownLatch(1);
        CountDownLatch finished = new CountDownLatch(2);
        AtomicInteger holding = new AtomicInteger();
        AtomicInteger crashes = new AtomicInteger();

        for (int i = 0; i < 2; i++) {
            daemon("reader-" + i, () -> {
                boolean held = false;
                try {
                    lock.lockRead();
                    held = true;
                    holding.incrementAndGet();
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                }
                settled.countDown();
                if (held) {
                    try {
                        release.await(HOLD_MS, TimeUnit.MILLISECONDS);
                        lock.unlockRead();
                    } catch (Throwable t) {
                        crashes.incrementAndGet();
                    }
                }
                finished.countDown();
            });
        }

        // Nobody has been released yet, so holding == 2 means both are inside simultaneously.
        boolean bothSettled = settled.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
        boolean ok = bothSettled && holding.get() == 2 && crashes.get() == 0;
        release.countDown();
        finished.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
        Atrophy.check("two readers hold the read lock at the same time", ok);
    }

    /** Check 2: a writer never overlaps a reader or another writer, over a bounded mixed run. */
    private static void exclusiveWriters() throws InterruptedException {
        final int ITER = 200;
        Solution lock = new Solution();
        AtomicInteger activeReaders = new AtomicInteger();
        AtomicInteger activeWriters = new AtomicInteger();
        AtomicInteger readOps = new AtomicInteger();
        AtomicInteger writeOps = new AtomicInteger();
        AtomicInteger crashes = new AtomicInteger();
        AtomicBoolean violation = new AtomicBoolean();
        CountDownLatch finished = new CountDownLatch(4);

        for (int i = 0; i < 2; i++) {
            daemon("mixed-reader-" + i, () -> {
                try {
                    for (int n = 0; n < ITER; n++) {
                        lock.lockRead();
                        activeReaders.incrementAndGet();
                        if (activeWriters.get() != 0) violation.set(true);
                        Thread.yield(); // widen the detection window; never a synchronization point
                        if (activeWriters.get() != 0) violation.set(true);
                        readOps.incrementAndGet();
                        activeReaders.decrementAndGet();
                        lock.unlockRead();
                    }
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                } finally {
                    finished.countDown();
                }
            });
        }
        for (int i = 0; i < 2; i++) {
            daemon("mixed-writer-" + i, () -> {
                try {
                    for (int n = 0; n < ITER; n++) {
                        lock.lockWrite();
                        int concurrentWriters = activeWriters.incrementAndGet();
                        if (concurrentWriters != 1 || activeReaders.get() != 0) violation.set(true);
                        Thread.yield();
                        if (activeWriters.get() != 1 || activeReaders.get() != 0) violation.set(true);
                        writeOps.incrementAndGet();
                        activeWriters.decrementAndGet();
                        lock.unlockWrite();
                    }
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                } finally {
                    finished.countDown();
                }
            });
        }

        boolean drained = finished.await(10, TimeUnit.SECONDS);
        boolean ok = drained
                && !violation.get()
                && crashes.get() == 0
                && readOps.get() == 2 * ITER
                && writeOps.get() == 2 * ITER;
        Atrophy.check("a writer never overlaps a reader or another writer", ok);
    }

    /** Check 3: a writer already queued behind a reader goes before a reader that arrives later. */
    private static void writePreference() throws InterruptedException {
        Solution lock = new Solution();
        AtomicInteger seq = new AtomicInteger();
        AtomicInteger writerOrder = new AtomicInteger();
        AtomicInteger lateReaderOrder = new AtomicInteger();
        AtomicInteger crashes = new AtomicInteger();
        AtomicBoolean firstReaderHeld = new AtomicBoolean();
        CountDownLatch firstSettled = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);
        CountDownLatch finished = new CountDownLatch(3);

        daemon("reader-first", () -> {
            boolean held = false;
            try {
                lock.lockRead();
                held = true;
                firstReaderHeld.set(true);
            } catch (Throwable t) {
                crashes.incrementAndGet();
            }
            firstSettled.countDown();
            if (held) {
                try {
                    release.await(HOLD_MS, TimeUnit.MILLISECONDS);
                    lock.unlockRead();
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                }
            }
            finished.countDown();
        });

        boolean ok = false;
        if (firstSettled.await(DEADLINE_MS, TimeUnit.MILLISECONDS) && firstReaderHeld.get()) {
            Thread writer = daemon("writer", () -> {
                try {
                    lock.lockWrite();
                    writerOrder.set(seq.incrementAndGet());
                    lock.unlockWrite();
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                }
                finished.countDown();
            });
            boolean writerQueued = awaitParked(writer, () -> writerOrder.get() != 0);

            Thread lateReader = daemon("reader-late", () -> {
                try {
                    lock.lockRead();
                    lateReaderOrder.set(seq.incrementAndGet());
                    lock.unlockRead();
                } catch (Throwable t) {
                    crashes.incrementAndGet();
                }
                finished.countDown();
            });
            boolean lateReaderQueued = awaitParked(lateReader, () -> lateReaderOrder.get() != 0);

            // Snapshot before the first reader lets go: neither may have gone in yet.
            boolean nobodyBarged = writerOrder.get() == 0 && lateReaderOrder.get() == 0;
            release.countDown();
            boolean drained = finished.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
            ok = writerQueued
                    && lateReaderQueued
                    && nobodyBarged
                    && writerOrder.get() == 1
                    && lateReaderOrder.get() == 2
                    && drained
                    && crashes.get() == 0;
        } else {
            release.countDown();
        }
        Atrophy.check("a queued writer goes ahead of a reader that arrives after it", ok);
    }
}
